98	  const [previewAsset, setPreviewAsset] =
99	    useState<EntityDetailsObjectInterface>();
100	  const { onAddGlossaryTerm } = useGlossaryStore();
101	  const { permissions } = useGenericContext<GlossaryTerm>();
102	  const { customizedPage, isLoading } = useCustomPages(PageType.GlossaryTerm);
103	  const { t } = useTranslation();
104	
105	  const assetPermissions = useMemo(() => {
106	    const glossaryTermStatus =
107	      glossaryTerm.entityStatus ?? EntityStatus.Approved;
108	
