120	      },
121	      { replace: true }
122	    );
123	  };
124	
125	  const handleFeedCount = useCallback((data: FeedCounts) => {
126	    setFeedCount(data);
127	  }, []);
128	
129	  const getEntityFeedCount = () => {
130	    getFeedCounts(
131	      EntityType.GLOSSARY_TERM,
132	      glossaryTerm.fullyQualifiedName ?? '',
133	      handleFeedCount
134	    );
135	  };
136	
137	  const fetchGlossaryTermAssets = async () => {
138	    if (glossaryTerm) {
139	      try {
140	        const res = await searchQuery({
141	          query: '',
142	          pageNumber: 1,
143	          pageSize: 0,
144	          queryFilter: getTermQuery({
145	            'tags.tagFQN': glossaryTerm.fullyQualifiedName ?? '',
146	          }),
147	          searchIndex: SearchIndex.ALL,
148	        });
149	
